export declare const receiptTheme = "/* \u8D2D\u7269\u5C0F\u7968\u98CE\u683C */\n#wemd {\n    padding: 5px 20px;\n    max-width: 677px;\n    margin: 0 auto;\n    /* \u5F3A\u5236\u7B49\u5BBD/\u886C\u7EBF\u5B57\u4F53\uFF0C\u6A21\u62DF\u6253\u5370\u673A */\n    font-family: \"Courier New\", \"SimSun\", \"Songti SC\", monospace;\n    color: #111;\n    background-color: transparent;\n    /* \u900F\u660E\u80CC\u666F\uFF0C\u517C\u5BB9\u5FAE\u4FE1\u6DF1\u8272\u6A21\u5F0F */\n    /* \u9876\u90E8\u6495\u7EB8\u6548\u679C */\n    border-top: 5px dashed #111;\n    border-bottom: 5px dashed #111;\n    word-break: break-word;\n}\n\n/* \u6B63\u6587 */\n#wemd p {\n    margin: 18px 0;\n    line-height: 1.6;\n    text-align: justify;\n    color: #222;\n    font-size: 15px;\n}\n\n/* \n * \u4E00\u7EA7\u6807\u9898 - \u5E97\u94FA\u62DB\u724C\u98CE\u683C\n * \u6539\u4E3A\uFF1A\u4E0A\u4E0B\u53CC\u865A\u7EBF\u5305\u88F9\uFF0C\u5C45\u4E2D\uFF0C\u52A0\u5927\u5B57\u91CD\n */\n#wemd h1 {\n    margin: 40px 0 30px;\n    text-align: center;\n    border-top: 2px dashed #000;\n    border-bottom: 2px dashed #000;\n    padding: 15px 0;\n}\n\n#wemd h1 .content {\n    font-size: 26px;\n    font-weight: 900;\n    color: #000;\n    letter-spacing: 2px;\n    display: block;\n    /* \u5360\u6EE1\u6574\u884C */\n    border: none;\n    /* \u53BB\u9664\u4E4B\u524D\u7684\u4E0B\u5212\u7EBF */\n}\n\n#wemd h1 .prefix,\n#wemd h1 .suffix {\n    display: none;\n}\n\n/* \u4E8C\u7EA7\u6807\u9898 - \u5206\u7C7B\u680F */\n#wemd h2 {\n    margin: 30px 0 20px;\n    text-align: center;\n}\n\n#wemd h2 .content {\n    display: block;\n    font-size: 18px;\n    font-weight: bold;\n    color: #fff;\n    /* \u53CD\u767D\u6587\u5B57 */\n    background: #000;\n    /* \u9ED1\u8272\u80CC\u666F\u6761 */\n    padding: 8px;\n}\n\n#wemd h2 .prefix,\n#wemd h2 .suffix {\n    display: none;\n}\n\n/* \u4E09\u7EA7\u6807\u9898 - \u52A0\u7C97\u9879\u76EE */\n#wemd h3 {\n    margin: 25px 0 10px;\n}\n\n#wemd h3 .content {\n    font-size: 16px;\n    font-weight: bold;\n    border-bottom: 2px solid #000;\n    padding-bottom: 2px;\n    display: inline-block;\n}\n\n#wemd h3 .prefix,\n#wemd h3 .suffix {\n    display: none;\n}\n\n/* \u56DB\u7EA7\u6807\u9898 - \u7B80\u5355\u6807\u7B7E */\n#wemd h4 {\n    margin: 20px 0 10px;\n    text-align: left;\n}\n\n#wemd h4 .content {\n    font-size: 16px;\n    font-weight: bold;\n    color: #000;\n    text-decoration: underline;\n}\n\n#wemd h4 .prefix,\n#wemd h4 .suffix {\n    display: none;\n}\n\n/* \u5F15\u7528 - \u5907\u6CE8\u6846 */\n#wemd .multiquote-1 {\n    margin: 25px 0;\n    padding: 15px;\n    border: 1px dotted #000;\n    /* \u70B9\u72B6\u8FB9\u6846 */\n    font-size: 14px;\n    text-align: left;\n    background: #f8f8f8;\n}\n\n#wemd .multiquote-1 p {\n    font-family: monospace;\n    color: #444;\n}\n\n#wemd .multiquote-2 {\n    margin: 22px 0;\n    padding: 13px;\n    border: 1px dashed #000;\n    background: #fafafa;\n}\n\n#wemd .multiquote-2 p {\n    font-family: monospace;\n    color: #444;\n}\n\n#wemd .multiquote-3 {\n    margin: 20px 0;\n    padding: 11px;\n    border: 1px dotted #666;\n    background: #fcfcfc;\n}\n\n#wemd .multiquote-3 p {\n    font-family: monospace;\n    color: #444;\n}\n\n/* \u5217\u8868 */\n#wemd ul {\n    list-style: none;\n    padding-left: 10px;\n    margin: 20px 0;\n}\n\n#wemd ul li {\n    margin-bottom: 8px;\n    border-bottom: 1px dotted #ccc;\n    /* \u4E0B\u5212\u7EBF\u8F85\u52A9\u9605\u8BFB */\n    padding-bottom: 4px;\n}\n\n#wemd ul li::before {\n    content: \"[*] \";\n    /* \u6A21\u62DF\u5B57\u7B26\u5217\u8868 */\n    font-weight: bold;\n    margin-right: 5px;\n}\n\n#wemd ol {\n    list-style: decimal;\n    padding-left: 25px;\n    margin: 20px 0;\n    font-weight: bold;\n}\n\n#wemd li section {\n    font-weight: normal;\n    color: #222;\n}\n\n#wemd ul ul {\n    list-style: none;\n    margin-top: 6px;\n}\n\n#wemd ul ul li::before {\n    content: \"[-] \";\n    font-weight: bold;\n}\n\n#wemd ol ol {\n    list-style-type: lower-alpha;\n}\n\n/* \u94FE\u63A5 */\n#wemd a {\n    color: #000;\n    text-decoration: underline;\n    font-weight: bold;\n}\n\n/* \u52A0\u7C97 */\n#wemd strong {\n    font-weight: 900;\n    background: #ddd;\n    /* \u6A21\u62DF\u7070\u8272\u9AD8\u4EAE\u6253\u5370 */\n    padding: 0 4px;\n}\n\n/* \u659C\u4F53 */\n#wemd em {\n    font-style: italic;\n    color: #000;\n}\n\n/* \u52A0\u7C97\u659C\u4F53 */\n#wemd em strong {\n    font-weight: 900;\n    font-style: italic;\n}\n\n/* \u9AD8\u4EAE - \u7070\u8272\u80CC\u666F */\n#wemd mark {\n    background: #ddd;\n    color: #000;\n    padding: 0 4px;\n}\n\n/* \u5220\u9664\u7EBF */\n#wemd del {\n    text-decoration: line-through;\n    color: #666;\n}\n\n/* \u5206\u5272\u7EBF - \u865A\u7EBF */\n#wemd hr {\n    margin: 30px 0;\n    border: none;\n    border-top: 2px dashed #000;\n}\n\n/* \u884C\u5185\u4EE3\u7801 - \u53CD\u8272\u6253\u5370\u5757 */\n#wemd p code,\n#wemd li code,\n#wemd td code,\n#wemd th code {\n    background: #000;\n    color: #fff;\n    font-family: monospace;\n    padding: 2px 6px;\n    margin: 0 4px;\n    font-size: 14px;\n    border-radius: 0;\n}\n\n/* \u56FE\u7247 - \u6296\u52A8\u8FB9\u6846 */\n#wemd img {\n    display: block;\n    margin: 30px auto;\n    width: 100%;\n    border: 2px dashed #000;\n    padding: 8px;\n    background: #fff;\n}\n\n#wemd figcaption {\n    margin-top: 8px;\n    text-align: center;\n    color: #000;\n    font-size: 13px;\n    font-family: monospace;\n    border-top: 1px dashed #000;\n    padding-top: 6px;\n}\n\n/* \n * \u4EE3\u7801\u5757 - \u66B4\u529B\u4FEE\u590D\u7248\n * 1. !important \u5F3A\u5236\u8986\u76D6\u7F16\u8F91\u5668\u7684\u6DF1\u8272\u4E3B\u9898\n * 2. \u53BB\u9664\u5706\u89D2\u548C\u9634\u5F71\n * 3. \u6A21\u62DF\u865A\u7EBF\u7EB8\u5F20\n */\n/* \u4EE3\u7801\u5757 - \u6CE8\u610F\uFF1A\u4E0D\u8981\u8BBE\u7F6E color\uFF0C\u8BA9\u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236\u6587\u5B57\u989C\u8272 */\n#wemd pre code.hljs {\n    background: #f4f4f4 !important;\n    /* \u5F3A\u5236\u6D45\u7070\u80CC\u666F */\n    /* color \u7531 .hljs \u8BED\u6CD5\u9AD8\u4EAE\u4E3B\u9898\u63A7\u5236 */\n    border: 2px dashed #000 !important;\n    /* \u5F3A\u5236\u865A\u7EBF\u6846 */\n    border-radius: 0 !important;\n    /* \u5F3A\u5236\u76F4\u89D2 */\n    box-shadow: none !important;\n    /* \u53BB\u6389\u7ACB\u4F53\u9634\u5F71 */\n    font-family: \"Courier New\", monospace;\n    font-size: 13px;\n    padding: 15px;\n    line-height: 1.5;\n}\n\n/* \u5982\u679C\u6CA1\u6709\u8BED\u6CD5\u9AD8\u4EAE\uFF0C\u8BBE\u7F6E\u9ED8\u8BA4\u9ED1\u8272 */\n#wemd pre code:not(.hljs) {\n    color: #000 !important;\n    background: #f4f4f4 !important;\n    border: 2px dashed #000 !important;\n    border-radius: 0 !important;\n    box-shadow: none !important;\n}\n\n/* \u5C1D\u8BD5\u9690\u85CF Mac \u7EA2\u7EFF\u706F (\u5982\u679C\u7F16\u8F91\u5668\u662F\u7528\u4F2A\u5143\u7D20\u5B9E\u73B0\u7684) */\n#wemd pre code::before {\n    content: \"\" !important;\n    display: none !important;\n}\n\n/* \u8868\u683C - \u4EF7\u683C\u5355 */\n#wemd table {\n    width: 100%;\n    border-collapse: collapse;\n    margin: 20px 0;\n    font-size: 14px;\n    font-family: monospace;\n}\n\n#wemd table tr th {\n    border-bottom: 2px dashed #000;\n    padding: 8px 5px;\n    text-align: right;\n    font-weight: 900;\n    text-transform: uppercase;\n}\n\n#wemd table tr th:first-child {\n    text-align: left;\n}\n\n#wemd table tr td {\n    border-bottom: 1px dotted #000;\n    padding: 8px 5px;\n    text-align: right;\n    color: #000;\n}\n\n#wemd table tr td:first-child {\n    text-align: left;\n}\n\n/* \u811A\u6CE8 */\n#wemd .footnote-word,\n#wemd .footnote-ref {\n    color: #000;\n    text-decoration: underline;\n}\n\n#wemd .footnotes-sep {\n    border-top: 2px dashed #000;\n    margin-top: 30px;\n    padding-top: 15px;\n}\n\n#wemd .footnote-num {\n    font-weight: bold;\n    color: #000;\n    margin-right: 4px;\n}\n\n#wemd .footnote-item p {\n    color: #444;\n    font-size: 13px;\n    font-family: monospace;\n}\n\n/* \u63D0\u793A\u5757 - \u8D2D\u7269\u5C0F\u7968\u98CE\u683C */\n#wemd .callout {\n    margin: 25px 0;\n    padding: 15px;\n    border: 1px dotted #000;\n    background: #f8f8f8;\n    border-radius: 0;\n}\n\n#wemd .callout-title {\n    font-weight: bold;\n    margin-bottom: 8px;\n    color: #000;\n    font-family: monospace;\n    text-transform: uppercase;\n    font-size: 14px;\n}\n\n#wemd .callout-icon { margin-right: 8px;\n    margin-right: 6px;\n}\n\n#wemd .callout-note { border-left: 2px dashed #000; }\n#wemd .callout-tip { border-left: 2px dashed #000; }\n#wemd .callout-important { border-left: 2px dashed #000; }\n#wemd .callout-warning { border-left: 2px dashed #000; }\n#wemd .callout-caution { border-left: 2px dashed #000; }\n\n/* Imageflow CSS */\n#wemd .imageflow-layer1 {\n  margin-top: 1em;\n  margin-bottom: 0.5em;\n  /* white-space: normal; */\n  border: 0px none;\n  padding: 0px;\n  overflow: hidden;\n}\n\n#wemd .imageflow-layer2 {\n  white-space: nowrap;\n  width: 100%;\n  overflow-x: scroll;\n}\n\n#wemd .imageflow-layer3 {\n  display: inline-block;\n  word-wrap: break-word;\n  white-space: normal;\n  vertical-align: top;\n  width: 80%;\n  margin-right: 10px;\n  flex-shrink: 0;\n}\n\n#wemd .imageflow-img {\n  display: block;\n  width: 100%;\n  height: auto;\n  max-height: 300px;\n  object-fit: contain;\n  border-radius: 4px;\n}\n\n#wemd .imageflow-caption {\n  text-align: center;\n  margin-top: 0px;\n  padding-top: 0px;\n  color: #888;\n}\n";
